parameters.jsCode:
const resume = $json;
const job = $('Webhook').first().json.body;
const jobRecord = $('Insert Job').first().json;

return [
  {
    json: {
      resume_id: resume.id,
      resume_name: resume.name,
      resume_text: resume.resume_text,

      job_id: jobRecord.id,
      company: job.company,
      job_title: job.job_title,
      job_url: job.job_url,
      job_description: job.job_description
    }
  }
];

const outputs = $json.output || [];

const message = outputs.find(item => item.type === 'message');

if (!message) {
  throw new Error('OpenAI message output was not found.');
}

const content = message.content?.find(
  item => item.type === 'output_text'
);

if (!content) {
  throw new Error('OpenAI output text was not found.');
}

let match = content.text;

// JSON Schema may return an object or a JSON string
if (typeof match === 'string') {
  try {
    match = JSON.parse(match);
  } catch (error) {
    throw new Error('OpenAI returned invalid JSON: ' + match);
  }
}

if (!match || typeof match !== 'object') {
  throw new Error('OpenAI did not return a valid match object.');
}

const input = $('Prepare Match Input').first().json;

const required = match.required_skills || [];
const matchedRequired = match.matched_required_skills || [];

const preferred = match.preferred_skills || [];
const matchedPreferred = match.matched_preferred_skills || [];

const requiredScore = required.length > 0
  ? (matchedRequired.length / required.length) * 60
  : 60;

const preferredScore = preferred.length > 0
  ? (matchedPreferred.length / preferred.length) * 20
  : 20;

const experienceScore = {
  Strong: 20,
  Moderate: 12,
  Weak: 5
}[match.experience_match] || 0;

const matchScore = Math.round(
  requiredScore + preferredScore + experienceScore
);

let recommendation;

if (matchScore >= 80) {
  recommendation = 'Apply';
} else if (matchScore >= 60) {
  recommendation = 'Consider';
} else {
  recommendation = 'Skip';
}

const matchedSkills = [
  ...matchedRequired,
  ...matchedPreferred
];

return [
  {
    json: {
      resume_id: input.resume_id,
      job_id: input.job_id,
      match_score: matchScore,
      matched_skills: JSON.stringify(matchedSkills),
      missing_skills: JSON.stringify(match.missing_skills || []),
      experience_match: match.experience_match,
      recommendation
    }
  }
];
